from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class CollectionCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str


class CollectionRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    name: str
    created_at: datetime
    updated_at: datetime


class CollectionPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "CollectionPatch":
        nullable = {
            "name": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BookmarkCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    url: str
    title: str
    starred: bool = False
    notes: str | None = None


class BookmarkRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    collection_id: int
    url: str
    title: str
    starred: bool
    notes: str | None
    created_at: datetime
    updated_at: datetime


class BookmarkPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    url: str | None = None
    title: str | None = None
    starred: bool | None = None
    notes: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "BookmarkPatch":
        nullable = {
            "url": False,
            "title": False,
            "starred": False,
            "notes": True,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: CollectionCreate
    children: list[BookmarkCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: CollectionRead
    children: list[BookmarkRead]

