from datetime import date
from fastapi import APIRouter, Depends, HTTPException, Query, Response
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session


from .models import Collection as Parent, Bookmark as Child
from .schemas import CollectionCreate as ParentCreate, CollectionRead as ParentRead, CollectionPatch as ParentPatch
from .schemas import BookmarkCreate as ChildCreate, BookmarkRead as ChildRead, BookmarkPatch as ChildPatch
from .schemas import BatchCreate, BatchRead


def create_router(get_session):
    router = APIRouter()

    def require_parent(db, parent_id):
        row = db.get(Parent, parent_id)
        if row is None:
            raise HTTPException(status_code=404, detail="parent not found")
        return row

    def require_child(db, parent_id, child_id):
        require_parent(db, parent_id)
        row = db.scalar(select(Child).where(Child.id == child_id, Child.collection_id == parent_id))
        if row is None:
            raise HTTPException(status_code=404, detail="child not found")
        return row

    def integrity_failure(db, exc, missing_parent=False):
        db.rollback()
        code = getattr(exc.orig, "sqlstate", None)
        if code == "23503" and missing_parent:
            raise HTTPException(status_code=404, detail="parent not found") from exc
        if code in {"23503", "23505"}:
            raise HTTPException(status_code=409, detail="relationship or unique value conflict") from exc
        raise exc

    @router.post("/collections/with-children", response_model=BatchRead, status_code=201)
    def create_batch(data: BatchCreate, db: Session = Depends(get_session)):
        parent = Parent(**data.parent.model_dump())
        children = []
        try:
            db.add(parent)
            db.flush()
            for item in data.children:
                child = Child(collection_id=parent.id, **item.model_dump())
                db.add(child)
                db.flush()
                children.append(child)
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(parent)
        for child in children:
            db.refresh(child)
        return {"parent": parent, "children": children}

    @router.delete("/collections/{parent_id}", status_code=204)
    def delete_parent(parent_id: int, db: Session = Depends(get_session)):
        row = require_parent(db, parent_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.post("/collections", response_model=ParentRead, status_code=201)
    def create_parent(data: ParentCreate, db: Session = Depends(get_session)):
        row = Parent(**data.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc, False)
        db.refresh(row)
        return row

    @router.get("/collections", response_model=list[ParentRead])
    def list_parent(limIt: int = Query(20, alias="limit", ge=1, le=50), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        statement = select(Parent)
        return list(db.scalars(statement.order_by(Parent.id).limit(limIt).offset(offset)))

    @router.get("/collections/{parent_id}", response_model=ParentRead)
    def get_parent(parent_id: int, db: Session = Depends(get_session)):
        return require_parent(db, parent_id)

    @router.delete("/collections/{parent_id}/bookmarks/{child_id}", status_code=204)
    def delete_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        db.delete(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        return Response(status_code=204)

    @router.patch("/collections/{parent_id}/bookmarks/{child_id}", response_model=ChildRead)
    def patch_child(parent_id: int, child_id: int, data: ChildPatch, db: Session = Depends(get_session)):
        row = require_child(db, parent_id, child_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.get("/collections/{parent_id}/bookmarks", response_model=list[ChildRead])
    def list_child(parent_id: int, starred: bool | None = None, limIt: int = Query(20, alias="limit", ge=1, le=25), offset: int = Query(0, ge=0), db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        statement = select(Child).where(Child.collection_id == parent_id)
        if starred is not None:
            statement = statement.where(Child.starred == starred)
        return list(db.scalars(statement.order_by(Child.id).limit(limIt).offset(offset)))

    @router.post("/collections/{parent_id}/bookmarks", response_model=ChildRead, status_code=201)
    def create_child(parent_id: int, data: ChildCreate, db: Session = Depends(get_session)):
        require_parent(db, parent_id)
        row = Child(collection_id=parent_id, **data.model_dump())
        db.add(row)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc, True)
        db.refresh(row)
        return row

    @router.patch("/collections/{parent_id}", response_model=ParentRead)
    def patch_parent(parent_id: int, data: ParentPatch, db: Session = Depends(get_session)):
        row = require_parent(db, parent_id)
        for name, value in data.model_dump(exclude_unset=True).items():
            setattr(row, name, value)
        try:
            db.commit()
        except IntegrityError as exc:
            integrity_failure(db, exc)
        db.refresh(row)
        return row

    @router.get("/collections/{parent_id}/bookmarks/{child_id}", response_model=ChildRead)
    def get_child(parent_id: int, child_id: int, db: Session = Depends(get_session)):
        return require_child(db, parent_id, child_id)

    return router

