from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class RecipeCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str
    servings: int


class RecipeRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    name: str
    servings: int
    created_at: datetime
    updated_at: datetime


class RecipePatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str | None = None
    servings: int | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "RecipePatch":
        nullable = {
            "name": False,
            "servings": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class IngredientCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str
    quantity: float
    unit: str
    notes: str | None = None


class IngredientRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    recipe_id: int
    name: str
    quantity: float
    unit: str
    notes: str | None
    created_at: datetime
    updated_at: datetime


class IngredientPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    name: str | None = None
    quantity: float | None = None
    unit: str | None = None
    notes: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "IngredientPatch":
        nullable = {
            "name": False,
            "quantity": False,
            "unit": False,
            "notes": True,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: RecipeCreate
    children: list[IngredientCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: RecipeRead
    children: list[IngredientRead]

