from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class DeviceCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    serial: str
    name: str


class DeviceRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    serial: str
    name: str
    created_at: datetime
    updated_at: datetime


class DevicePatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    serial: str | None = None
    name: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "DevicePatch":
        nullable = {
            "serial": False,
            "name": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class InspectionCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    summary: str
    passed: bool
    follow_up: bool = False
    next_check_on: date | None = None


class InspectionRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    device_id: int
    summary: str
    passed: bool
    follow_up: bool
    next_check_on: date | None
    created_at: datetime
    updated_at: datetime


class InspectionPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    summary: str | None = None
    passed: bool | None = None
    follow_up: bool | None = None
    next_check_on: date | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "InspectionPatch":
        nullable = {
            "summary": False,
            "passed": False,
            "follow_up": False,
            "next_check_on": True,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: DeviceCreate
    children: list[InspectionCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: DeviceRead
    children: list[InspectionRead]

