from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class ExperimentCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    code: str
    title: str


class ExperimentRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    code: str
    title: str
    created_at: datetime
    updated_at: datetime


class ExperimentPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    code: str | None = None
    title: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "ExperimentPatch":
        nullable = {
            "code": False,
            "title": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class ObservationCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    sample_count: int
    value: float
    reading: float | None = None
    verified: bool = False


class ObservationRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    experiment_id: int
    sample_count: int
    value: float
    reading: float | None
    verified: bool
    created_at: datetime
    updated_at: datetime


class ObservationPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    sample_count: int | None = None
    value: float | None = None
    reading: float | None = None
    verified: bool | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "ObservationPatch":
        nullable = {
            "sample_count": False,
            "value": False,
            "reading": True,
            "verified": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: ExperimentCreate
    children: list[ObservationCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: ExperimentRead
    children: list[ObservationRead]

