from datetime import date, datetime
from pydantic import BaseModel, ConfigDict, Field, model_validator


class BoundedInput(BaseModel):
    model_config = ConfigDict(extra="forbid", allow_inf_nan=False)

    @model_validator(mode="after")
    def bounded_values(self):
        for name in self.model_fields_set:
            value = getattr(self, name)
            if isinstance(value, str) and len(value) > 255:
                raise ValueError("strings must have at most 255 characters")
            if type(value) is int and not -(2**31) <= value < 2**31:
                raise ValueError("integers must fit signed 32 bits")
        return self


class DocumentCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    reference: str
    title: str


class DocumentRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    reference: str
    title: str
    created_at: datetime
    updated_at: datetime


class DocumentPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    reference: str | None = None
    title: str | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "DocumentPatch":
        nullable = {
            "reference": False,
            "title": False,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class ReviewCreate(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    reviewer: str
    score: float | None = None
    notes: str | None = None
    approved: bool = False
    review_by: date | None = None


class ReviewRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: int
    document_id: int
    reviewer: str
    score: float | None
    notes: str | None
    approved: bool
    review_by: date | None
    created_at: datetime
    updated_at: datetime


class ReviewPatch(BoundedInput):
    model_config = ConfigDict(extra="forbid")
    reviewer: str | None = None
    score: float | None = None
    notes: str | None = None
    approved: bool | None = None
    review_by: date | None = None

    @model_validator(mode="after")
    def reject_null_for_required_columns(self) -> "ReviewPatch":
        nullable = {
            "reviewer": False,
            "score": True,
            "notes": True,
            "approved": False,
            "review_by": True,
        }
        for field in self.model_fields_set:
            if getattr(self, field) is None and not nullable[field]:
                raise ValueError(f"{field} cannot be null")
        return self


class BatchCreate(BaseModel):
    model_config = ConfigDict(extra="forbid")
    parent: DocumentCreate
    children: list[ReviewCreate] = Field(min_length=1, max_length=20)


class BatchRead(BaseModel):
    parent: DocumentRead
    children: list[ReviewRead]

